/**
 * Bundled agent skills shipped to every Maya workspace.
 *
 * Each entry materializes at deploy as skills/<slug>/SKILL.md inside the
 * workspace tarball. OpenClaw's skill loader auto-discovers them from
 * the workspace's skills/ directory (under ~/.openclaw/workspace-default).
 *
 * The SKILL.md content is inlined as a TS string constant so it ships
 * through Convex's V8 runtime (no fs.readFileSync available there). The
 * source of truth is the on-disk file under agents/skills/<slug>/SKILL.md;
 * the scripts/sync-bundled-skills.ts helper keeps this file in sync. A test
 * in __tests__/assembleWorkspaceBundle.test.ts verifies the in-bundle bytes
 * match the on-disk file byte-for-byte.
 *
 * Regenerate (from repo root):
 *   npx tsx scripts/sync-bundled-skills.ts
 *
 * DO NOT EDIT BY HAND — re-run the sync script instead.
 */

export interface BundledSkill {
  /** Skill directory name under `agents/skills/<slug>/`. */
  slug: string;
  /** Raw markdown content of `SKILL.md`. */
  content: string;
}

